  function cleanCount(value){if(!['number','string'].includes(typeof value))return null;if(value===null||value===undefined||String(value).trim()==='')return null;const n=Number(value);return Number.isSafeInteger(n)&&n>=0&&n<=1000000000?n:null;}
  function normaliseProfiles(items){return (Array.isArray(items)?items:[]).filter(x=>x&&typeof x==='object').map((x,i)=>({name:typeof x.name==='string'?x.name.trim().slice(0,120):'',description:typeof x.description==='string'?x.description.trim().slice(0,800):'',population:cleanCount(x.population),reachable:cleanCount(x.reachable),target:cleanCount(x.target)})).filter(x=>x.name||x.description||[x.population,x.reachable,x.target].some(n=>n!==null)).slice(0,10).map((x,i)=>({...x,name:x.name||`Profile ${i+1}`}));}
  function validFinishDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number(value.slice(0,4))<1900||Number(value.slice(0,4))>2100)return '';const d=new Date(value+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===value?value:'';}
  function normalisePlanning(p){p.profiles=normaliseProfiles(p.profiles);p.context.finishDate=validFinishDate(p.context.finishDate);return p;}
  function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
