    const dates=[];for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+1))if(d.getUTCDay()!==0&&d.getUTCDay()!==6)dates.push(d.toISOString().slice(0,10));
    const current=Math.max(0,phases.findIndex(ph=>ph.id===p.context.stage)),last=Math.max(current,phases.findIndex(ph=>ph.id==='share')),remaining=phases.slice(current,last+1);
