    let leftover=dates.length-allocations.reduce((a,b)=>a+b,0);const fractions=remaining.map((ph,i)=>({i,f:(extra*weights[ph.id]/total)%1})).sort((a,b)=>b.f-a.f);for(let i=0;i<leftover;i++)allocations[fractions[i].i]++;
    let offset=0;const rows=remaining.map((ph,i)=>{const from=dates[offset],to=dates[offset+allocations[i]-1];offset+=allocations[i];return {phase:ph,from,to,days:allocations[i]};});
