  function contextPlanningPreview(){const fd=new FormData($('#contextForm')),profiles=normaliseProfiles(readFormProfiles(fd)),finish=validFinishDate(String(fd.get('finishDate')||'')),draft={profiles,context:{...project().context,finishDate:finish,stage:String(fd.get('stage')||project().context.stage)}},plan=timelinePlan(draft),warnings=profileWarnings(profiles);$('#contextPlanningPreview').innerHTML=(profiles.length?`<p>${profiles.length} profile${profiles.length===1?'':'s'} recorded. Counts are per group; overlapping groups are not a combined sample.</p>`:'')+(finish?`<p>Finish by <strong>${dateLabel(finish)}</strong>. ${plan.status==='past'?'This date has passed.':plan.status==='distant'?'Choose a nearer window for a working timeline.':`${plan.weekdays} weekday${plan.weekdays===1?'':'s'} available from today.`} ${plan.status==='short'?'This is shorter than one weekday per remaining stage. Agree a narrower scope before committing.':''}</p>`:'')+warnings.map(w=>`<p class="planning-warning">${esc(w)}</p>`).join('');}
  function peopleSummary(){const p=project();return [p.context.users,...p.profiles.map(pr=>`${pr.name}${pr.description?' — '+pr.description:''}`)].filter(Boolean).join(' · ');}
  function planningPanel(phase){const p=project(),plan=timelinePlan();if(!p.profiles.length&&plan.status==='none')return '';return `<details class="project-planning" ${phase==='plan'?'open':''}><summary>People & timeline${p.profiles.length?' · '+p.profiles.length+' profile'+(p.profiles.length===1?'':'s'):''}${plan.finish?' · finish '+dateLabel(plan.finish):''}</summary><div class="project-planning-body">${p.profiles.length?`<h3>User profiles & recruitment</h3><p class="planning-note">Counts are per profile. Groups may overlap; do not treat their sum as an independent sample.</p><div class="guide-table-wrap" role="region" aria-label="User profiles and research counts" tabindex="0"><table class="guide-table profile-table"><thead><tr><th scope="col">Profile / persona</th><th scope="col">Group size</th><th scope="col">Reachable</th><th scope="col">Planned participants / responses</th></tr></thead><tbody>${p.profiles.map(pr=>`<tr><th scope="row">${esc(pr.name)}${pr.description?`<small>${esc(pr.description)}</small>`:''}</th><td>${pr.population??'Unknown'}</td><td>${pr.reachable??'Unknown'}</td><td>${pr.target??'Not set'}</td></tr>`).join('')}</tbody></table></div>${profileWarnings().map(w=>`<p class="planning-warning">${esc(w)}</p>`).join('')}<p class="planning-note">Planned counts are recruitment targets, not proof of statistical sufficiency. For quantitative claims, define the population, recruitment, measure, intended comparison and precision. <a href="#guide/sampling">Review sampling & coverage →</a></p>`:''}<h3>Provisional research timeline</h3>${plan.status==='none'?'<p class="planning-note">Add a finish date in project context to sketch the remaining stages.</p>':plan.status==='past'?`<p class="planning-warning">The finish date, ${dateLabel(plan.finish)}, has passed. Update the date or record the project’s closeout status.</p>`:plan.status==='distant'?'<p class="planning-note">Choose a nearer planning window to sketch the remaining work.</p>':`<p class="planning-note">Finish by <strong>${dateLabel(plan.finish)}</strong> · ${plan.weekdays} weekday${plan.weekdays===1?'':'s'} available from today.</p>${plan.status==='short'?`<p class="planning-warning">Only ${plan.weekdays} weekday${plan.weekdays===1?' remains':'s remain'} for ${plan.stages} stages. Agree what can realistically be completed, what to narrow and what will follow later.</p>`:`<div class="timeline-list">${plan.rows.map(row=>`<div><a href="#phase/${row.phase.id}">${row.phase.name}</a><span>${dateLabel(row.from)} → ${dateLabel(row.to)}</span><small>${row.days} weekday${row.days===1?'':'s'}</small></div>`).join('')}</div>`}<p class="planning-note">This is a planning sketch from your current stage through sharing findings, not a delivery estimate. It reserves time for analysis and sharing. Review recruitment lead time, team capacity, holidays and the work already done; archive and retrospective can follow.</p>`}<button class="button small quiet" data-action="context">Update people & finish date ↗</button></div></details>`;}
  function planningMarkdown(){const p=project(),plan=timelinePlan();return `\n## User profiles & recruitment targets\n\n${p.profiles.length?p.profiles.map(pr=>`- ${pr.name}${pr.description?' — '+pr.description:''}: group size ${pr.population??'unknown'}; reachable ${pr.reachable??'unknown'}; planned participants / responses ${pr.target??'not set'}.`).join('\n'):'No structured profiles recorded.'}\n\nCounts are per profile; groups can overlap. Targets do not establish statistical sufficiency.\n\n## Provisional timeline\n\nFinish date: ${p.context.finishDate||'Not set'}\n\n${plan.rows.length?plan.rows.map(r=>`- ${r.phase.name}: ${r.from} to ${r.to} (${r.days} weekdays).`).join('\n'):plan.status==='past'?'Finish date has passed.':plan.status==='short'?'Insufficient weekdays for one day per remaining stage; review scope.':'No stage schedule generated.'}\n\nReview recruitment, analysis capacity, holidays and the remaining scope before committing.\n`;}
  function normaliseResources(p){p.readiness=cleanReadiness(p.readiness);normaliseProblems(p);normalisePlanning(p);p.selectedMethods=Array.isArray(p.selectedMethods)?p.selectedMethods.filter(id=>guideById(id)?.kind==='method'):[];p.issues=Array.isArray(p.issues)?p.issues.filter(id=>difficulties.some(d=>d.id===id)):[];p.templateNotes=p.templateNotes&&typeof p.templateNotes==='object'?p.templateNotes:{};p.methodSelection=p.methodSelection&&typeof p.methodSelection==='object'?p.methodSelection:{};return p;}
