    const planTitles={explore:'Choose evidence that explains needs and workflows',evaluate:'Plan an evaluation that can answer the decision',measure:'Define comparable measures before collecting data',align:'Plan evidence-led alignment with the team'};
    const collectTitles={explore:'Understand needs and current workflows',evaluate:'Evaluate realistic tasks and understand the friction',measure:'Collect comparable evidence for the outcome',align:'Make assumptions and priorities explicit'};
